  const fs = require('fs');

  // Make the script executable
  fs.chmodSync('/tmp/mcp-workspace/apply_patch.sh', '755');

  // Execute the script
  return new Promise((resolve, reject) => {
    exec('bash /tmp/mcp-workspace/apply_patch.sh', (error, stdout, stderr) => {
      if (error) {
        reject(`Error: ${error.message}`);
        return;
      }
      if (stderr) {
        resolve(`Stderr: ${stderr}`);
        return;
      }
      resolve(`Output: ${stdout}`);
    });
  });
}

